<script lang="ts">
 import {tr} from '../services/preferences';import RichMarkup from './RichMarkup.svelte';export let workflow:any;export let illustrative=false;
 const rich=(text:any)=>String(text||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/\*\*(.*?)\*\*/g,'<strong>$1</strong>');
</script>
<article class="paper imported-workflow"><h2>{workflow?.title||$tr('流程待补充')}</h2>{#if illustrative}<p class="notice">{$tr('流程中的工时与井数是教学情境设定，并非当前运行实测。')}</p>{/if}{#each workflow?.lead||[] as text}<RichMarkup html={'<p>'+rich(text)+'</p>'}/>{/each}{#if workflow?.stats?.length}<div class="workflow-stats">{#each workflow.stats as row}<div><span>{row[0]}</span><strong>{row[1]}</strong></div>{/each}</div>{/if}<ol class="imported-steps">{#each workflow?.steps||[] as step,i}<li><span class="section-no">{String(i+1).padStart(2,'0')} {step.role||''}</span><h3>{step.name}</h3><RichMarkup html={'<p>'+rich(step.do)+'</p>'}/>{#if step.effect}<div class="step-result"><strong>{$tr('预期结果')}</strong><RichMarkup html={rich(step.effect)}/></div>{/if}{#if step.trap}<div class="notice"><strong>{$tr('注意事项')}</strong><RichMarkup html={rich(step.trap)}/></div>{/if}</li>{/each}</ol>{#if workflow?.metrics}<section class="workflow-metrics"><h3>{workflow.metrics.title||$tr('评估方式')}</h3><RichMarkup html={workflow.metrics.html||''}/></section>{/if}{#if workflow?.fails?.length}<section class="workflow-failures"><h3>{$tr('失败情形与边界')}</h3>{#each workflow.fails as failure}<details><summary>{failure.name}</summary><RichMarkup html={'<p>'+rich(failure.why)+'</p>'}/></details>{/each}</section>{/if}</article>
